def transform(grid):
    g = np.asarray(grid)
    bg = background(g)
    out = np.full_like(g, bg)
    emit(out, "Clear the canvas: every template shape and every stray single cell is erased; the output is rebuilt from scratch.")

    objs = objects(g, bg=bg, diagonal=True, multicolour=True)
    singles = [o["cells"][0] for o in objs if o["size"] == 1]
    templates = [o for o in objs if o["size"] >= 2]

    for o in templates:
        # marker = the least frequent colour inside the shape (exactly one cell)
        counts = {}
        for (y, x) in o["cells"]:
            counts[g[y, x]] = counts.get(g[y, x], 0) + 1
        mk = min(counts, key=counts.get)
        anchor = [(y, x) for (y, x) in o["cells"] if g[y, x] == mk][0]
        stamped = 0
        for (sy, sx) in singles:
            if g[sy, sx] != mk:
                continue
            for (y, x) in o["cells"]:
                ny, nx = y - anchor[0] + sy, x - anchor[1] + sx
                if 0 <= ny < g.shape[0] and 0 <= nx < g.shape[1]:
                    out[ny, nx] = g[y, x]
            stamped += 1
        if stamped:
            emit(out, f"Stamp the template whose marker colour is {mk} onto each of the {stamped} lone cell(s) of colour {mk}, aligning the marker cell with the lone cell.")

    emit(out, "Final canvas: all templates copied to their marker positions; unmatched lone cells discarded.")
    return out
